def main():
    items, states = base.proposals()
    errors = base.validate(items, states)
    if errors:
        raise ValueError(errors)
    if len(items) != 143:
        raise ValueError(f'Expected 143 authored cases, got {len(items)}')
    for item in items:
        item['problem']['authoring']['batch'] = 'engineering-batch5'
    counts = {tool: sum(item['problem']['tool_id'] == tool for item in items) for tool in states}
    wrapper = {
        'schema_version': 1,
        'proposal_version': '2026.10.27.engineering-batch5',
        'publication_status': 'unregistered_proposals',
        'proposals': items,
        'counts': {'proposed_promotions': len(items), 'published_added': 0, 'by_technology': counts},
        'validation': {'structural_errors': errors, 'runtime_claim': 'Fixture contracts authored; learner code and platform execution remain unverified.'},
    }
    path = base.OUT / 'engineering-promotions5.json'
    temporary = path.with_suffix('.json.tmp')
    temporary.write_text(json.dumps(wrapper, indent=2, ensure_ascii=False) + '\n', encoding='utf-8', newline='\n')
    temporary.replace(path)
    checkpoint = {
        'state': 'prepared_not_published', 'proposed': len(items), 'published_added': 0,
        'counts': counts, 'proposal_sha256': hashlib.sha256(path.read_bytes()).hexdigest(),
        'source_files_sha256': {tool: hashlib.sha256(state['path'].read_bytes()).hexdigest() for tool, state in states.items()},
        'errors': errors,
    }
    (base.OUT / 'authors/engineering-batch5-checkpoint.json').write_text(json.dumps(checkpoint, indent=2) + '\n', encoding='utf-8')
    print(json.dumps(checkpoint, indent=2))

if __name__ == '__main__':
    main()
